/**
 * Adapt aliases into runnable cmd.js entries.
 * @param {(alias) => Function} makeRun  builds the click handler per alias
 */
export function toCommands(makeRun) {
  return API_ALIASES.map((a) => ({ ...a, run: makeRun(a) }));
}
